package vn.vinhkhang.warehouse;
import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;
@RestController @RequestMapping("/api/receipts") public class VehicleReceipts {
 private final Api core;private final JdbcTemplate db;public VehicleReceipts(Api core,JdbcTemplate db){this.core=core;this.db=db;}
 @GetMapping public Object list(@RequestHeader("Authorization") String t){core.user(t,false);return db.queryForList("SELECT r.*,COUNT(v.id) quantity FROM vehicle_receipts r LEFT JOIN vehicles v ON v.receipt_id=r.id WHERE r.deleted=FALSE GROUP BY r.id ORDER BY r.id DESC");}
 Map<String,Object> record(long id){var rs=db.queryForList("SELECT * FROM vehicle_receipts WHERE id=? AND deleted=FALSE FOR UPDATE",id);if(rs.isEmpty())throw new Api.Problem(404,"Không tìm thấy phiếu nhập xe");var r=new LinkedHashMap<String,Object>(rs.getFirst());r.put("vehicles",db.queryForList("SELECT v.*,m.name model FROM vehicles v JOIN vehicle_models m ON m.id=v.model_id WHERE receipt_id=?",id));return r;}
 @GetMapping("/{id}") @Transactional public Object get(@RequestHeader("Authorization") String t,@PathVariable long id){core.user(t,false);return record(id);}
 @PostMapping @Transactional public Object create(@RequestHeader("Authorization") String t,@RequestBody Map<String,Object> m){var s=core.user(t,true);long id=core.insert("INSERT INTO vehicle_receipts(code,source,note,created_by) VALUES(?,?,?,?)",core.str(m,"code"),core.str(m,"source"),m.get("note"),s.id());int count=0;for(var v:core.lines(m,"vehicles")){int quantity=VehicleTypes.quantity(v);count+=quantity;if(count>1000)throw new Api.Problem(400,"Một phiếu nhập tối đa 1000 xe");long model=core.num(v,"model_id");core.active("vehicle_models",model);String type=VehicleTypes.type(v),frame=VehicleTypes.serial(core,v,"frame_number"),motor=VehicleTypes.serial(core,v,"motor_number");for(int i=0;i<quantity;i++)db.update("INSERT INTO vehicles(model_id,receipt_id,color,vehicle_type,frame_number,motor_number,purchase_unit_cost) VALUES(?,?,?,?,?,?,?)",model,id,core.str(v,"color"),type,frame,motor,AccountKinds.get(db,s.id()).equals("FACTORY")?Costing.cost(v,"purchase_unit_cost"):RevenueReports.money(v,"purchase_unit_cost",false));}core.audit(s,"RECEIVE","receipts",id);return Map.of("id",id);}
 @PutMapping("/{id}") @Transactional public void edit(@RequestHeader("Authorization") String t,@PathVariable long id,@RequestBody Map<String,Object> m){var s=core.user(t,true);record(id);db.update("UPDATE vehicle_receipts SET code=?,source=?,note=? WHERE id=?",core.str(m,"code"),core.str(m,"source"),m.get("note"),id);core.audit(s,"UPDATE","receipts",id);}
 @DeleteMapping("/{id}") @Transactional public void remove(@RequestHeader("Authorization") String t,@PathVariable long id,@RequestBody Map<String,Object> m){var s=core.admin(t);var before=record(id);core.str(m,"reason");var vs=db.queryForList("SELECT id,status,deleted FROM vehicles WHERE receipt_id=? FOR UPDATE",id);if(vs.stream().anyMatch(v->!"AVAILABLE".equals(v.get("STATUS"))||Boolean.TRUE.equals(v.get("DELETED"))))throw new Api.Problem(409,"Không thể hủy nhập xe đã xuất hoặc đã xóa. Hãy hoàn tác phiếu xuất trước.");DeletedRecords.capture(db,new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules(),"receipts",id,before);db.update("UPDATE vehicles SET deleted=TRUE WHERE receipt_id=?",id);db.update("UPDATE vehicle_receipts SET deleted=TRUE WHERE id=?",id);if(before.get("PRODUCTION_ORDER_ID")!=null)ProductionProgress.refresh(db,((Number)before.get("PRODUCTION_ORDER_ID")).longValue());core.audit(s,"DELETE","receipts",id);}
}

